ltac2:(KReplay.run1 (kr_t_AsDrvRead ()) [] "p;1p;2p;3p10000p4p70p1000`p4p710R0p8p1001>p4p70P0p8p1001lp4p7210P0p8g002Xj10Tg003=j13Tg003[j16Tg004>j14Tg004`j11Tg005Ej1<Tg005cj2;Tg006Vj35Tg0079j22Tg007[j27Tg0085j28Tg008[j29Tg009]j3:Tg00:7R0#0#0#0#0#0R1#3R2#6R3#4R4%10#1#0#0#1#1#<R01;20552,23'7g00:\%01#3g00;S'8'9g00<S,235:4do"). Qed.

Lemma amem_inv_wbytes_data : forall m (A : Z) bs,
  mem_inv asegs m -> 0x17c000 <= A -> A < 2 ^ 64 -> A + Z.of_nat (length bs) <= 2 ^ 64 ->
